import { z } from 'zod';
import { DEVICE_STATUS } from '../enums.js';
import { text, sha256Hex } from './common.js';

// The caller supplies only a hash; the secret itself is generated by the device service and shown once.
export const deviceRegisterSchema = z.strictObject({
  credentialHash: sha256Hex,
  model: text(2, 100).nullable().default(null),
  pollIntervalSec: z.number().int().min(30).max(3600).default(300),
});

// Heartbeat/telemetry: the only device-writable fields.
export const deviceTelemetrySchema = z.strictObject({
  firmwareVersion: text(1, 32).optional(),
  batteryPct: z.number().int().min(0).max(100).optional(),
  signalCsq: z.number().int().min(0).max(99).optional(),
  queuedUploads: z.number().int().min(0).max(10_000).optional(),
  droppedUploads: z.number().int().min(0).max(1_000_000).optional(),
});

// `unassigned` is reachable only by registering a device, never by setting a status.
export const deviceStatusSchema = z.enum(DEVICE_STATUS.filter((s) => s !== 'unassigned'));

/** Why an admin changed a status (shown in the audit trail). */
export const statusReasonSchema = text(3, 200);
